// ---------------------------------------------------------------------------
// HTML fallback
// ---------------------------------------------------------------------------

/**
 * Generate an HTML invoice for local display when server PDF is unavailable.
 * Returns complete HTML string suitable for rendering in a WebView.
 */
export function generateInvoiceHtml(invoice: InvoiceDetail): string {
  const fmt = (n: number) => n.toFixed(2).replace('.', ',');

  const actRows = invoice.acts.length > 0
    ? invoice.acts
        .map(
          (a) =>
            `<tr><td class="code">${esc(a.code)}</td><td>${esc(a.label)}</td><td class="amt">${fmt(a.amount)} &euro;</td></tr>`,
        )
        .join('\n')
    : '<tr><td colspan="3" class="empty">Actes non detailles</td></tr>';

  const statusLabel =
    invoice.status === 'validated'
      ? 'Validee'
      : invoice.status === 'draft'
      ? 'Brouillon'
      : invoice.status;

  return `<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: -apple-system, system-ui, sans-serif; background: #F8FAFC; color: #1E293B; padding: 24px 16px; }
  .header { text-align: center; margin-bottom: 24px; }
  .header h1 { font-size: 20px; font-weight: 800; }
  .header .number { font-size: 14px; color: #64748B; margin-top: 4px; }
  .badge { display: inline-block; padding: 3px 10px; border-radius: 6px; font-size: 12px; font-weight: 700; background: ${invoice.status === 'validated' ? '#DCFCE7' : '#FFF7ED'}; color: ${invoice.status === 'validated' ? '#16A34A' : '#EA580C'}; }
  .info { background: #fff; border: 1px solid #E2E8F0; border-radius: 10px; padding: 14px; margin-bottom: 20px; }
  .info-row { display: flex; justify-content: space-between; padding: 6px 0; border-bottom: 1px solid #F1F5F9; }
  .info-row:last-child { border-bottom: none; }
  .info-row .label { color: #64748B; font-size: 13px; }
  .info-row .value { font-weight: 600; font-size: 14px; }
  table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #E2E8F0; border-radius: 10px; overflow: hidden; margin-bottom: 20px; }
  th { background: #F1F5F9; text-align: left; padding: 8px 12px; font-size: 11px; text-transform: uppercase; color: #64748B; letter-spacing: 0.5px; }
  td { padding: 10px 12px; border-top: 1px solid #F1F5F9; font-size: 13px; }
  .code { font-weight: 700; color: #2563EB; white-space: nowrap; }
  .amt { text-align: right; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .empty { color: #94A3B8; font-style: italic; }
  .totals { background: #fff; border: 1px solid #E2E8F0; border-radius: 10px; overflow: hidden; }
  .total-row { display: flex; justify-content: space-between; padding: 10px 14px; border-bottom: 1px solid #F1F5F9; }
  .total-row:last-child { border-bottom: none; }
  .total-row.main { font-weight: 800; font-size: 15px; background: #F8FAFC; }
  .total-row .label { font-size: 13px; color: #64748B; }
  .total-row .value { font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }
  .zero { color: #16A34A; }
  .footer { text-align: center; margin-top: 32px; font-size: 11px; color: #94A3B8; }
</style>
</head>
<body>
  <div class="header">
    <h1>Facture</h1>
    <div class="number">N&deg; ${esc(invoice.invoiceNumber)}</div>
    <div style="margin-top:8px"><span class="badge">${esc(statusLabel)}</span></div>
  </div>

  <div class="info">
    <div class="info-row"><span class="label">Patient</span><span class="value">${esc(invoice.patientName)}</span></div>
    <div class="info-row"><span class="label">Date</span><span class="value">${esc(invoice.date)}</span></div>
    <div class="info-row"><span class="label">Montant total</span><span class="value" style="font-size:16px;font-weight:800">${fmt(invoice.totalAmount)} &euro;</span></div>
  </div>

  <table>
    <tr><th>Code</th><th>Acte</th><th style="text-align:right">Montant</th></tr>
    ${actRows}
  </table>

  <div class="totals">
    <div class="total-row main"><span>TOTAL</span><span>${fmt(invoice.totalAmount)} &euro;</span></div>
    <div class="total-row"><span class="label">Part AMO (Secu)</span><span class="value">${fmt(invoice.amountAmo)} &euro;</span></div>
    <div class="total-row"><span class="label">Part complementaire</span><span class="value">${fmt(invoice.amountAmc)} &euro;</span></div>
    <div class="total-row"><span class="label">Reste a charge patient</span><span class="value${invoice.amountPatient === 0 ? ' zero' : ''}">${fmt(invoice.amountPatient)} &euro;</span></div>
  </div>

  <div class="footer">Document genere localement &mdash; IDEL Assistant</div>
</body>
</html>`;
}

function esc(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
